import os
import hmac
import hashlib
import json
from flask import Flask, request, jsonify, redirect
from urllib.parse import urlparse, parse_qs, urlencode
import requests
import redis
import time

app = Flask(__name__)

OAUTH_CLIENT_ID = os.environ.get('OAUTH_CLIENT_ID')
OAUTH_CLIENT_SECRET = os.environ.get('OAUTH_CLIENT_SECRET')
REDIS_URL = os.environ.get('REDIS_URL', 'redis://localhost:6379')
SESSION_SECRET = os.environ.get('SESSION_SECRET', 'dev-secret-key')

rc = redis.from_url(REDIS_URL)

ALLOWED_REDIRECT_DOMAINS = ['app.example.com', 'dashboard.example.com']

def generate_state(session_id, redirect_uri):
    payload = json.dumps({'sid': session_id, 'redirect': redirect_uri, 'ts': int(time.time())})
    sig = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    return f"{payload}|{sig}"

def verify_state(state_param):
    try:
        payload, sig = state_param.rsplit('|', 1)
        expected = hmac.new(SESSION_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        if hmac.compare_digest(sig, expected):
            return json.loads(payload)
    except (ValueError, json.JSONDecodeError):
        pass
    return None

@app.route('/auth/login')
def login():
    redirect_uri = request.args.get('next', 'https://app.example.com/dashboard')
    session_id = request.cookies.get('session_id', os.urandom(16).hex())
    state = generate_state(session_id, redirect_uri)
    rc.setex(f"oauth_state:{session_id}", 300, state)
    params = {
        'client_id': OAUTH_CLIENT_ID,
        'redirect_uri': 'https://api.example.com/auth/callback',
        'response_type': 'code',
        'scope': 'openid profile email',
        'state': state
    }
    return redirect(f"https://accounts.google.com/o/oauth2/v2/auth?{urlencode(params)}")

@app.route('/auth/callback')
def callback():
    code = request.args.get('code')
    state_param = request.args.get('state')

    if not code or not state_param:
        return jsonify({'error': 'missing params'}), 400

    state_data = verify_state(state_param)
    if not state_data:
        return jsonify({'error': 'invalid state'}), 403

    # Exchange code for token
    token_resp = requests.post('https://oauth2.googleapis.com/token', data={
        'client_id': OAUTH_CLIENT_ID,
        'client_secret': OAUTH_CLIENT_SECRET,
        'code': code,
        'grant_type': 'authorization_code',
        'redirect_uri': 'https://api.example.com/auth/callback'
    })

    if token_resp.status_code != 200:
        return jsonify({'error': 'token exchange failed'}), 502

    tokens = token_resp.json()
    id_token = tokens.get('id_token')

    # Store session
    session_id = state_data['sid']
    rc.setex(f"session:{session_id}", 86400, json.dumps({
        'id_token': id_token,
        'access_token': tokens.get('access_token'),
        'authenticated_at': int(time.time())
    }))

    # Redirect to the original destination
    redirect_target = state_data.get('redirect', 'https://app.example.com/dashboard')

    # Validate redirect target
    parsed = urlparse(redirect_target)
    if parsed.scheme not in ('https', 'http'):
        redirect_target = 'https://app.example.com/dashboard'

    response = redirect(redirect_target)
    response.set_cookie('session_id', session_id, httponly=True, secure=True, samesite='Lax')
    return response

@app.route('/auth/userinfo')
def userinfo():
    session_id = request.cookies.get('session_id')
    if not session_id:
        return jsonify({'error': 'not authenticated'}), 401

    session_data = rc.get(f"session:{session_id}")
    if not session_data:
        return jsonify({'error': 'session expired'}), 401

    data = json.loads(session_data)
    return jsonify({'authenticated': True, 'authenticated_at': data['authenticated_at']})

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
